Below is a possible implementation of the FavoritesManager class and a corresponding FavoritesController. The FavoritesManager encapsulates the logic for adding/removing favorites either in the database (for authenticated users) or in the session (for guests). The FavoritesController then exposes an API to the frontend. Feel free to adapt it to match your database schema (e.g., if you have a different table/fields).

-------------------------------------------------------------------------------
App\Favorites\FavoritesManager.php
-------------------------------------------------------------------------------
<?php

namespace App\Favorites;

use App\Models\Favorite;
use App\Models\User;
use Illuminate\Support\Facades\Session;

/**
 * Manages the user's favorite names, either by storing them
 * in the database (for authenticated users) or in the session (for guests).
 */
class FavoritesManager
{
    /**
     * Add a name to the list of favorites.
     *
     * @param  string  $name
     * @param  User|null  $user
     * @return void
     */
    public function addFavorite(string $name, ?User $user): void
    {
        if ($user) {
            $this->addFavoriteToDatabase($user, $name);
        } else {
            $this->addFavoriteToSession($name);
        }
    }

    /**
     * Remove a name from the list of favorites.
     *
     * @param  string  $name
     * @param  User|null  $user
     * @return void
     */
    public function removeFavorite(string $name, ?User $user): void
    {
        if ($user) {
            $this->removeFavoriteFromDatabase($user, $name);
        } else {
            $this->removeFavoriteFromSession($name);
        }
    }

    /**
     * Get all favorites for a user or guest.
     *
     * @param  User|null  $user
     * @return array
     */
    public function getFavorites(?User $user): array
    {
        if ($user) {
            return $user->favorites()->pluck('name')->toArray();
        }

        return Session::get('favorites', []);
    }

    /**
     * Handle adding a new favorite to the database.
     *
     * @param  User   $user
     * @param  string $name
     * @return void
     */
    protected function addFavoriteToDatabase(User $user, string $name): void
    {
        // Only add if not already favorited
        $exists = $user->favorites()->where('name', $name)->exists();
        if (!$exists) {
            $favorite = new Favorite();
            $favorite->user_id = $user->id;
            $favorite->name = $name;
            $favorite->save();
        }
    }

    /**
     * Handle removing an existing favorite from the database.
     *
     * @param  User   $user
     * @param  string $name
     * @return void
     */
    protected function removeFavoriteFromDatabase(User $user, string $name): void
    {
        $user->favorites()->where('name', $name)->delete();
    }

    /**
     * Handle adding a new favorite in the session (guest).
     *
     * @param  string $name
     * @return void
     */
    protected function addFavoriteToSession(string $name): void
    {
        $favorites = Session::get('favorites', []);

        // Avoid duplicates in session
        if (!in_array($name, $favorites)) {
            $favorites[] = $name;
            Session::put('favorites', $favorites);
        }
    }

    /**
     * Handle removing an existing favorite from the session (guest).
     *
     * @param  string $name
     * @return void
     */
    protected function removeFavoriteFromSession(string $name): void
    {
        $favorites = Session::get('favorites', []);
        if (($key = array_search($name, $favorites)) !== false) {
            unset($favorites[$key]);
            Session::put('favorites', array_values($favorites));
        }
    }
}

