App\Http\Controllers\FavoritesController.php
-------------------------------------------------------------------------------
<?php

namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class FavoritesController extends Controller
{
    protected $favoritesManager;

    /**
     * Constructor injection of the FavoritesManager.
     */
    public function __construct(FavoritesManager $favoritesManager)
    {
        $this->favoritesManager = $favoritesManager;
    }

    /**
     * Add a new favorite name.
     *
     * Route: POST /api/favorites/add
     * Body: { "name": "Some Business Name" }
     */
    public function add(Request $request)
    {
        $request->validate([
            'name' => 'required|string',
        ]);

        $this->favoritesManager->addFavorite($request->input('name'), Auth::user());

        return response()->json([
            'message' => 'Favorite added successfully.',
            'favorites' => $this->favoritesManager->getFavorites(Auth::user()),
        ]);
    }

    /**
     * Remove a favorite name.
     *
     * Route: POST /api/favorites/remove
     * Body: { "name": "Some Business Name" }
     */
    public function remove(Request $request)
    {
        $request->validate([
            'name' => 'required|string',
        ]);

        $this->favoritesManager->removeFavorite($request->input('name'), Auth::user());

        return response()->json([
            'message' => 'Favorite removed successfully.',
            'favorites' => $this->favoritesManager->getFavorites(Auth::user()),
        ]);
    }

    /**
     * Retrieve all favorites for the current user or guest (session).
     *
     * Route: GET /api/favorites
     */
    public function index()
    {
        $favorites = $this->favoritesManager->getFavorites(Auth::user());

        return response()->json([
            'favorites' => $favorites,
        ]);
    }
}

