E) client/src/TodoList.js
-------------------------
import React, { useEffect, useState } from "react";
import TodoItem from "./TodoItem";

const TodoList = () => {
  const [todos, setTodos] = useState([]);

  const getTodos = async () => {
    try {
      const response = await fetch("http://localhost:5000/todos");
      const jsonData = await response.json();
      setTodos(jsonData);
    } catch (err) {
      console.error(err.message);
    }
  };

  useEffect(() => {
    getTodos();
  }, []);

  return (
    <ul>
      {todos.map((todo) => (
        <TodoItem key={todo.todo_id} todo={todo} onUpdate={getTodos} />
      ))}
    </ul>
  );
};

export default TodoList;

F) client/src/TodoItem.js
-------------------------
import React, { useState } from "react";

const TodoItem = ({ todo, onUpdate }) => {
  const [editing, setEditing] = useState(false);
  const [description, setDescription] = useState(todo.description);

  const updateTodo = async () => {
    try {
      await fetch(`http://localhost:5000/todos/${todo.todo_id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ description }),
      });
      setEditing(false);
      onUpdate(); // Refresh the list
    } catch (err) {
      console.error(err.message);
    }
  };

  const deleteTodo = async () => {
    try {
      await fetch(`http://localhost:5000/todos/${todo.todo_id}`, {
        method: "DELETE",
      });
      onUpdate(); // Refresh the list
    } catch (err) {
      console.error(err.message);
    }
  };

  return (
    <li style={{ marginBottom: "0.5rem" }}>
      {editing ? (
        <>
          <input
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <button onClick={updateTodo}>Save</button>
          <button onClick={() => setEditing(false)}>Cancel</button>
        </>
      ) : (
        <>
          {description}
          <button onClick={() => setEditing(true)} style={{ marginLeft: "1rem" }}>
            Edit
          </button>
          <button onClick={deleteTodo} style={{ marginLeft: "0.5rem" }}>
            Delete
          </button>
        </>
      )}
    </li>
  );
};

export default TodoItem;

───────────────────────────────
5) Running the Application
───────────────────────────────

1) Start the Server
   ----------------
   cd server
   npm run dev
   (This uses nodemon, so it will restart automatically when you change server files.)

2) Start the React Client
   ----------------------
   cd client
   npm start
   (This starts the React dev server on port 3000 by default.)

3) Access the App
   --------------
   Go to http://localhost:3000 in your browser. You can add todos, edit them, and delete them.

───────────────────────────────
Additional Notes
───────────────────────────────
• Make sure your PostgreSQL connection details in db.js match your local setup.  
• For production or deployment, you would typically:  
  1. Build the React app (npm run build)  
  2. Serve those static files from your Express server.  
  3. Configure environment variables for your database credentials.  

──────────────────────────────────────────────────────────────────
That’s it! You have a basic PERN stack To-Do List application. Enjoy!

Below is a sample Java program that prompts the user to enter two positive integers, calculates their greatest common divisor (GCD) using Euclid’s algorithm, and displays the result:

import java.util.Scanner;

public class GCDProgram {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user for the first positive integer
        System.out.print("Enter the first positive integer: ");
        int num1 = scanner.nextInt();

        // Prompt the user for the second positive integer
        System.out.print("Enter the second positive integer: ");
        int num2 = scanner.nextInt();

        // Compute the GCD
        int gcd = findGCD(num1, num2);

        // Display the GCD
        System.out.println("The GCD of " + num1 + " and " + num2 + " is " + gcd);

        scanner.close();
    }

    // Method to find GCD of two numbers using Euclid’s algorithm
    public static int findGCD(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}

Explanation:  
1. We use a Scanner to read two positive integers from System.in.  
2. The findGCD method implements Euclid's algorithm: as long as b is not zero, you repeatedly set temp = a % b, update a to b, and b to temp. This process continues until b becomes zero, at which point a contains the GCD.  
3. Finally, we print the computed GCD.

