Below is a simple example of how you can create a stream (Iterator) of prime numbers in Rust by defining a custom struct and implementing Iterator for it. This example uses a straightforward (though not the most efficient) primality check.

--------------------------------------------------------------------------------
use std::iter::Iterator;

/// A small helper function to check if a number is prime using a naive approach.
fn is_prime(num: u64) -> bool {
    if num < 2 {
        return false;
    }
    let limit = (num as f64).sqrt() as u64;
    for i in 2..=limit {
        if num % i == 0 {
            return false;
        }
    }
    true
}

/// A struct that will act as our prime number generator.
pub struct Primes {
    current: u64,
}

impl Primes {
    pub fn new() -> Self {
        Primes { current: 1 }
    }
}

impl Iterator for Primes {
    type Item = u64;

    /// Returns the next prime number, incrementing from the last.
    fn next(&mut self) -> Option<Self::Item> {
        // Find the next prime by incrementing until we see a prime.
        loop {
            self.current += 1;
            if is_prime(self.current) {
                return Some(self.current);
            }
        }
    }
}

fn main() {
    // Create an iterator of prime numbers.
    let primes = Primes::new();

    // For demonstration, take the first 20 primes and print them.
    for (index, prime) in primes.take(20).enumerate() {
        println!("Prime {}: {}", index + 1, prime);
    }
}
--------------------------------------------------------------------------------

Explanation:
• The Primes struct holds a current field that tracks where we are in our search for primes.
• We define new() just to initialize current to 1.
• The Iterator implementation’s next() method increments current and checks whether the new value is prime. If it is, next() returns Some(prime); otherwise, it keeps looping.
• The is_prime function performs a naive primality check by testing divisibility from 2 up to the square root of the number.
• The main function demonstrates usage by taking the first 20 primes and printing them out.

You can adapt this code as needed—for example, by making the primality test or the prime generation more efficient with a sieve or by caching primes.

Below is a simple example of how one might implement an elementary RNN in TypeScript without relying on external libraries. The code includes the steps needed to:

• Initialize weight and bias matrices.  
• Compute the forward pass for a sequence of vectors.  
• Demonstrate a simple usage example.  

This is meant to be educational, so it focuses on clarity rather than efficiency or completeness.

--------------------------------------------------------------------------------

/**
 * A minimal RNN implementation using plain TypeScript.
 * Based on the standard RNN equations:
 *
 *    h_t = tanh(W_hh · h_(t-1) + W_xh · x_t + b_h)
 *    y_t = W_hy · h_t + b_y
 *
 * The code below:
 *   1. Defines small utility functions for matrix/vector operations.
 *   2. Initializes a SimpleRNN class with random parameters.
 *   3. Implements a forward(...) method to run the RNN on an input sequence.
 */

// ------------------------------------------------------------
// 1. Utility functions
// ------------------------------------------------------------

/** Create a rows x cols matrix filled with a given value (default 0). */
function createMatrix(rows: number, cols: number, fill: number = 0): number[][] {
  const matrix: number[][] = [];
  for (let i = 0; i < rows; i++) {
    const row: number[] = new Array(cols).fill(fill);
    matrix.push(row);
  }
  return matrix;
}

/** Generate a rows x cols matrix with random values in [-0.1, 0.1]. */
function randomMatrix(rows: number, cols: number): number[][] {
  const matrix = createMatrix(rows, cols);
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      // small random range
      matrix[i][j] = Math.random() * 0.2 - 0.1;
    }
  }
  return matrix;
}

/** Create a length-n vector with random values in [-0.1, 0.1]. */
function randomVector(n: number): number[] {
  const v = new Array(n);
  for (let i = 0; i < n; i++) {
    v[i] = Math.random() * 0.2 - 0.1;
  }
  return v;
}

/** Elementwise addition of vector a and b (same length). */
function addVectors(a: number[], b: number[]): number[] {
  const result = new Array(a.length);
  for (let i = 0; i < a.length; i++) {
    result[i] = a[i] + b[i];
  }
  return result;
}

/** Elementwise tanh on a vector. */
function tanhVector(vec: number[]): number[] {
  return vec.map(Math.tanh);
}

/** Matrix-vector multiplication: result = M · v. 
 *  M is size (rows x cols), v is size (cols x 1).
 */
function matVecMul(M: number[][], v: number[]): number[] {
  const rows = M.length;
  const cols = M[0].length;
  const result = new Array(rows).fill(0);

  for (let i = 0; i < rows; i++) {
    let sum = 0;
    for (let j = 0; j < cols; j++) {
      sum += M[i][j] * v[j];
    }
    result[i] = sum;
  }
  return result;
}

/** Elementwise addition of two vectors in-place. (Helper function) */
function addVectorsInPlace(target: number[], source: number[]): void {
  for (let i = 0; i < target.length; i++) {
    target[i] += source[i];
  }
}

// ------------------------------------------------------------
// 2. Simple RNN class definition
// ------------------------------------------------------------

class SimpleRNN {
  // Weight matrices
  private Wxh: number[][];  // from input to hidden
  private Whh: number[][];  // from hidden (previous state) to hidden (current)
  private Why: number[][];  // from hidden to output

  // Bias vectors
  private bh: number[];  // for hidden
  private by: number[];  // for output

  // Hidden state
  private h: number[];   // holds the current hidden state

  constructor(
    inputDim: number,
    hiddenDim: number,
    outputDim: number
  ) {
    // Randomly initialize the matrices/parameters
    this.Wxh = randomMatrix(hiddenDim, inputDim);
    this.Whh = randomMatrix(hiddenDim, hiddenDim);
    this.Why = randomMatrix(outputDim, hiddenDim);

    // Randomly initialize bias vectors
    this.bh = randomVector(hiddenDim);
    this.by = randomVector(outputDim);

    // Initialize hidden state to zeros
    this.h = new Array(hiddenDim).fill(0);
  }

  /**
   * Reset the hidden state to zeros (useful if you run multiple sequences
   * independently).
   */
  public resetHiddenState(): void {
    this.h.fill(0);
  }

  /**
   * Run the RNN forward on a sequence of input vectors.
   * Returns an array of output vectors (one per time step).
   *
   * @param inputs - an array of input vectors. 
   *                 Each input vector has dimension = inputDim.
   */
  public forward(inputs: number[][]): number[][] {
    const outputs: number[][] = [];

    for (const x of inputs) {
      // h_t = tanh(W_hh * h_(t-1) + W_xh * x_t + b_h)
      let hiddenUpdate = matVecMul(this.Whh, this.h);  // Whh * h_{t-1}
      addVectorsInPlace(hiddenUpdate, matVecMul(this.Wxh, x));  // + Wxh * x_t
      addVectorsInPlace(hiddenUpdate, this.bh);                 // + b_h
      this.h = tanhVector(hiddenUpdate);                        // tanh(...)

      // y_t = W_hy * h_t + b_y
      let output = matVecMul(this.Why, this.h); // Why * h_t
      addVectorsInPlace(output, this.by);       // + b_y

      outputs.push(output);
    }

    return outputs;
  }
}

// ------------------------------------------------------------
// 3. Usage example
// ------------------------------------------------------------

function main() {
  // Specify dimensions
  const inputDim = 3;   // e.g. input vector is length 3
  const hiddenDim = 4;  // hidden layer size
  const outputDim = 2;  // output is length 2

  // Create the RNN
  const rnn = new SimpleRNN(inputDim, hiddenDim, outputDim);

  // Dummy sequence of three time steps
  const sequence: number[][] = [
    [1.0, 0.5, -1.0],  // x_1
    [0.0, 2.0,  1.0],  // x_2
    [1.0, 1.0,  1.0]   // x_3
  ];

  // Run forward pass
  const outputs = rnn.forward(sequence);

  // Print the result
  console.log("Outputs at each time step:");
  outputs.forEach((outVec, t) => {
    console.log(`t=${t}, y=${outVec}`);
  });
}

// Uncomment to run main (if you're using this in a standalone .ts file).
// main();

--------------------------------------------------------------------------------

Explanation:

1. Utility Functions:  
   - createMatrix, randomMatrix, and randomVector help create new matrices/vectors with default or random initial values.  
   - matVecMul implements a straightforward matrix × vector multiplication.  
   - tanhVector applies the hyperbolic tangent function to each component of a vector (we use tanh as the RNN’s activation).  

2. SimpleRNN Class:  
   - The constructor takes inputDim, hiddenDim, and outputDim and creates the relevant weight/bias matrices and vectors.  
   - forward(...) processes a sequence of input vectors, updating the hidden state h at each time step and producing an output y.   
   - resetHiddenState() is used to reinitialize the hidden state for processing a fresh sequence (optional, but often useful).  

3. Usage Example:  
   - Shows how to create an instance of SimpleRNN, build a mock input sequence, and invoke forward(...) to get the RNN outputs.  

Note: This example does not include training or backpropagation. Extending the code to handle gradient computation and parameter updates would significantly increase its length and complexity. However, this serves as a working reference for the basic RNN forward pass in plain TypeScript.

Below is a basic example of a simple web-based sprite (pixel) editor in JavaScript. It provides an interactive grid where you can pick a color and click on squares (a “pixel”) to fill them. You can also export/import the sprite data as JSON for sharing or saving purposes. 

Feel free to adapt this code to your project’s specific needs, styles, or functionalities.

--------------------------------------------------------------------------------
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>Simple Sprite Editor</title>
  <style>
    body {
      font-family: sans-serif;
      margin: 20px;
    }

    #editor-container {
      display: flex;
      flex-wrap: wrap;
    }

    /* Grid styling */
    .pixel {
      width: 20px;
      height: 20px;
      border: 1px solid #ccc;
      box-sizing: border-box;
      cursor: pointer;
    }

    /* Color palette styling */
    #color-palette {
      display: flex;
      gap: 10px;
      margin-bottom: 1em;
    }

    .color-swatch {
      width: 24px;
      height: 24px;
      cursor: pointer;
      border: 2px solid transparent;
    }

    .color-swatch.selected {
      border: 2px solid black;
    }

    #controls {
      margin-top: 20px;
    }

    textarea {
      width: 100%;
      height: 80px;
    }
  </style>
</head>
<body>

  <h1>Simple Sprite Editor</h1>

  <!-- Color palette section -->
  <div id="color-palette"></div>

  <!-- Pixel grid container -->
  <div id="editor-container"></div>

  <!-- JSON export/import and buttons -->
  <div id="controls">
    <button id="export-btn">Export Sprite</button>
    <button id="import-btn">Import Sprite</button>
    <br><br>
    <textarea id="sprite-data" placeholder="Sprite data in JSON will appear here"></textarea>
  </div>

  <script>
    // -----------------------------------------------
    // Configuration
    // -----------------------------------------------
    const gridWidth = 16;  // Number of columns in the grid
    const gridHeight = 16; // Number of rows in the grid

    // You can modify or extend this color list as you wish
    const colors = [
      '#000000', // black
      '#ffffff', // white
      '#ff0000', // red
      '#00ff00', // green
      '#0000ff', // blue
      '#ffff00', // yellow
      '#ff00ff', // magenta
      '#00ffff'  // cyan
    ];

    // -----------------------------------------------
    // Global state
    // -----------------------------------------------
    let currentColor = '#000000';
    // We'll keep track of the grid as a 2D array of color codes
    let spriteData = Array.from(Array(gridHeight), () => Array(gridWidth).fill('#ffffff'));

    // -----------------------------------------------
    // Build the color palette
    // -----------------------------------------------
    const paletteContainer = document.getElementById('color-palette');

    colors.forEach(color => {
      const swatch = document.createElement('div');
      swatch.classList.add('color-swatch');
      swatch.style.backgroundColor = color;

      // Pick a color on click
      swatch.addEventListener('click', () => {
        currentColor = color;
        refreshPaletteSelection(color);
      });

      paletteContainer.appendChild(swatch);
    });

    // Helper to update which swatch is "selected"
    function refreshPaletteSelection(selectedColor) {
      const swatches = document.querySelectorAll('.color-swatch');
      swatches.forEach(swatch => {
        if (swatch.style.backgroundColor === selectedColor) {
          swatch.classList.add('selected');
        } else {
          swatch.classList.remove('selected');
        }
      });
    }
    // Initially select the first color
    refreshPaletteSelection(currentColor);

    // -----------------------------------------------
    // Build the pixel grid
    // -----------------------------------------------
    const editorContainer = document.getElementById('editor-container');

    for (let row = 0; row < gridHeight; row++) {
      for (let col = 0; col < gridWidth; col++) {
        const pixelDiv = document.createElement('div');
        pixelDiv.classList.add('pixel');
        pixelDiv.style.backgroundColor = spriteData[row][col];

        pixelDiv.addEventListener('click', () => {
          // Change the pixel to the current color
          spriteData[row][col] = currentColor;
          pixelDiv.style.backgroundColor = currentColor;
        });

        editorContainer.appendChild(pixelDiv);
      }
    }

    // -----------------------------------------------
    // Export/Import controls
    // -----------------------------------------------
    const exportBtn = document.getElementById('export-btn');
    const importBtn = document.getElementById('import-btn');
    const spriteDataTextarea = document.getElementById('sprite-data');

    // Export current sprite data to JSON
    exportBtn.addEventListener('click', () => {
      const data = JSON.stringify(spriteData);
      spriteDataTextarea.value = data;
    });

    // Import sprite data from JSON
    importBtn.addEventListener('click', () => {
      try {
        const data = JSON.parse(spriteDataTextarea.value);
        if (Array.isArray(data) && data.length === gridHeight) {
          spriteData = data;
          // Re-render the grid with new sprite data
          const pixels = editorContainer.querySelectorAll('.pixel');
          let i = 0;
          for (let row = 0; row < gridHeight; row++) {
            for (let col = 0; col < gridWidth; col++) {
              pixels[i].style.backgroundColor = spriteData[row][col];
              i++;
            }
          }
        } else {
          alert('Invalid sprite data');
        }
      } catch (err) {
        alert('Error parsing sprite data: ' + err.message);
      }
    });
  </script>
</body>
</html>
--------------------------------------------------------------------------------

Explanation:
1. Configuration: You can adjust the gridWidth and gridHeight for your desired sprite size.  
2. Colors: This is a basic color palette; add or remove colors as needed.  
3. State: spriteData is a 2D array representing the color of each pixel.  
4. Building the Editor:  
   • We create a palette of color swatches.  
   • We create a grid of clickable “pixel” divs. Each pixel’s background color matches spriteData.  
   • When you click a pixel, its color changes to the currently selected color.  
5. Export/Import:  
   • “Export Sprite” turns the spriteData array into JSON so you can copy/share it.  
   • “Import Sprite” parses the JSON from the textarea and updates the grid accordingly.  

This setup gives you a starting point for a basic sprite editor. You can enhance it with features such as multiple frames for animation, zoom levels, or advanced tools (e.g., eraser, fill, line drawing).

Below is a simple example showing how you can fetch data from "/get_session" using @tanstack/vue-query, select specific fields, and then update a Pinia store. The main steps are:

1. Create or import a Pinia store that has state and actions/mutations for updating.  
2. Use useQuery from @tanstack/vue-query in your component to fetch and transform the data.  
3. Update the store (in onSuccess or using the select option) with just the keys that matter.

Example store (e.g., session.ts):

import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    userId: null,
    username: '',
    // add other session-related keys
  }),
  actions: {
    setSession(partialSession) {
      Object.assign(this, partialSession)
    },
  },
})

Example usage in a component that uses @tanstack/vue-query (e.g., SessionView.vue):

<template>
  <div>
    <p v-if="isLoading">Loading session...</p>
    <p v-else-if="isError">Error loading session.</p>
    <div v-else>
      <p>User ID: {{ sessionStore.userId }}</p>
      <p>Username: {{ sessionStore.username }}</p>
      <!-- show other session info -->
    </div>
  </div>
</template>

<script setup>
import { storeToRefs } from 'pinia'
import { useQuery } from '@tanstack/vue-query'
import { useSessionStore } from '@/stores/session'

// 1. Prepare your store
const sessionStore = useSessionStore()
const { userId, username } = storeToRefs(sessionStore)

// 2. Create a fetch function for "/get_session"
async function fetchSession() {
  const response = await fetch('/get_session')
  if (!response.ok) {
    throw new Error('Failed to fetch session')
  }
  return response.json()
}

// 3. Use Vue Query to fetch and automatically update store
const { isLoading, isError, data } = useQuery({
  queryKey: ['session'],
  queryFn: fetchSession,

  // "select" transforms the raw response—only pick the fields you want
  // to store in Pinia. (You could also do this in onSuccess below.)
  select: (rawResponse) => {
    return {
      userId: rawResponse.user_id,       // adapt key names as needed
      username: rawResponse.user_name,
    }
  },

  // "onSuccess" handles what happens after a successful fetch. 
  // You can update your Pinia store here with the selected data.
  onSuccess: (selectedData) => {
    sessionStore.setSession(selectedData)
  },
})
</script>

Explanation:

• fetchSession: A simple async function that calls /get_session and returns JSON.  
• select: A configuration in Vue Query that lets you transform or pick fields from the response; you might rename keys or omit unneeded fields.  
• onSuccess: Runs whenever the query succeeds. In this example, we call sessionStore.setSession(...) to push the selected data into Pinia.  
• storeToRefs: Allows you to watch reactivity for sessionStore fields in the template.  

That’s it! With this pattern, your Pinia store will automatically be kept up to date with just the keys you want from the /get_session response.

